/**
 * Local cover store (M5).
 *
 * The cover binary is a FILE under <data-dir>/covers/; the database keeps the
 * file reference (`cover_file`), never a remote URL. The binary route
 * (GET /api/articles/:id/cover) serves the bytes from here.
 *
 * Layout:
 *   <data-dir>/covers/<articleId>-<n>.<ext>
 *
 * Rules:
 *   - the file name is generated by this module only;
 *   - every read validates the name against the naming convention
 *     (<uuid>-<n>.<ext>) and against the owning article id — a crafted name
 *     can never escape the covers directory;
 *   - deleting an article removes its cover files (delete cascade).
 */
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { join } from 'node:path';

import { resolveDataDir } from './data-dir.mjs';

/** Directory name under the data dir that holds the cover binaries. */
export const COVERS_DIR_NAME = 'covers';

/**
 * SEC-04 (CWE-276): the cover store creates PRIVATE paths.
 *
 * The data dir may be pointed at a shared location (--data-dir /tmp/...), so
 * the covers directory and the binaries must not rely on the parent being
 * private. POSIX: 0700 for the directory, 0600 for the files. On Windows these
 * bits are not the security boundary (NTFS ACLs are) — same semantics as
 * data-dir.mjs / secret-store.mjs.
 */
export const COVERS_DIR_MODE = 0o700;
export const COVER_FILE_MODE = 0o600;

const CONTENT_TYPES = new Map([
  ['png', 'image/png'],
  ['jpeg', 'image/jpeg'],
  ['jpg', 'image/jpeg'],
  ['webp', 'image/webp'],
  ['gif', 'image/gif'],
]);

const FALLBACK_CONTENT_TYPE = 'application/octet-stream';

/** <uuid>-<n>.<ext> — the only shape this store writes and accepts. */
const COVER_FILENAME_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}-(\d+)\.([a-z0-9]+)$/i;

/**
 * Resolve (and create) the covers directory of a data dir.
 * @param {object} [opts]
 * @param {string} [opts.dataDir] - data dir (default: resolveDataDir())
 * @returns {string} absolute path to <data-dir>/covers
 */
export function resolveCoversDir(opts = {}) {
  const dir = join(opts.dataDir || resolveDataDir(), COVERS_DIR_NAME);
  mkdirSync(dir, { recursive: true, mode: COVERS_DIR_MODE });
  return dir;
}

/**
 * Content type for a file extension.
 * @param {string} ext
 * @returns {string}
 */
export function coverContentType(ext) {
  const key = String(ext ?? '')
    .trim()
    .toLowerCase()
    .replace(/^\./, '');
  return CONTENT_TYPES.get(key) ?? FALLBACK_CONTENT_TYPE;
}

/**
 * The binary route of an article (GET /api/articles/:id/cover).
 * @param {string} articleId
 * @returns {string}
 */
export function coverRouteFor(articleId) {
  return `/api/articles/${articleId}/cover`;
}

/**
 * Is this a file name the store may read or delete?
 * Only names that match the generated convention are accepted — a crafted
 * name (../.., absolute path, plain name) is rejected.
 * @param {unknown} name
 * @returns {boolean}
 */
export function isSafeCoverFilename(name) {
  if (typeof name !== 'string') return false;
  return COVER_FILENAME_PATTERN.test(name.trim());
}

/**
 * Is this file name owned by the given article?
 * @param {string} name
 * @param {string} articleId
 * @returns {boolean}
 */
export function isCoverFilenameOfArticle(name, articleId) {
  if (!isSafeCoverFilename(name)) return false;
  if (typeof articleId !== 'string' || !articleId) return false;
  return name.trim().toLowerCase().startsWith(`${articleId.toLowerCase()}-`);
}

/**
 * Write a cover binary into the store.
 *
 * @param {object} args
 * @param {string} args.articleId - owning article (UUID)
 * @param {Buffer} args.buffer - image bytes
 * @param {string} [args.ext='png'] - file extension (without dot)
 * @param {string} [args.dataDir] - data dir (default: resolveDataDir())
 * @returns {{ filename: string, path: string, contentType: string, bytes: number, route: string }}
 */
export function saveCoverBinary({ articleId, buffer, ext = 'png', dataDir } = {}) {
  if (typeof articleId !== 'string' || !articleId.trim()) {
    throw new Error('cover-store: articleId is required');
  }
  if (!Buffer.isBuffer(buffer) && !(buffer instanceof Uint8Array)) {
    throw new Error('cover-store: buffer is required');
  }
  const dir = resolveCoversDir({ dataDir });
  const safeExt = String(ext ?? 'png')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '') || 'png';

  const nextIndex = nextCoverIndex(dir, articleId);
  const filename = `${articleId}-${nextIndex}.${safeExt}`;
  const path = join(dir, filename);
  writeFileSync(path, buffer, { mode: COVER_FILE_MODE });

  return {
    filename,
    path,
    contentType: coverContentType(safeExt),
    bytes: buffer.length,
    route: coverRouteFor(articleId),
  };
}

/**
 * Read a stored cover.
 *
 * @param {object} args
 * @param {string} args.articleId - owning article (UUID)
 * @param {string} args.file - file name stored in the DB
 * @param {string} [args.dataDir] - data dir (default: resolveDataDir())
 * @returns {{ filename: string, buffer: Buffer, contentType: string } | null}
 */
export function readCoverBinary({ articleId, file, dataDir } = {}) {
  if (!isCoverFilenameOfArticle(file, articleId)) return null;
  const dir = resolveCoversDir({ dataDir });
  const path = join(dir, file.trim());
  if (!existsSync(path)) return null;

  let buffer;
  try {
    buffer = readFileSync(path);
  } catch {
    return null;
  }
  const match = COVER_FILENAME_PATTERN.exec(file.trim());
  return {
    filename: file.trim(),
    buffer,
    contentType: coverContentType(match?.[2] ?? ''),
  };
}

/**
 * Remove every cover file of an article (delete cascade).
 *
 * @param {string} articleId
 * @param {object} [opts]
 * @param {string} [opts.dataDir] - data dir (default: resolveDataDir())
 * @returns {number} how many files were removed
 */
export function removeArticleCovers(articleId, opts = {}) {
  if (typeof articleId !== 'string' || !articleId.trim()) return 0;
  const dir = resolveCoversDir(opts);
  let entries = [];
  try {
    entries = readdirSync(dir);
  } catch {
    return 0;
  }

  let removed = 0;
  for (const entry of entries) {
    if (!isCoverFilenameOfArticle(entry, articleId)) continue;
    try {
      rmSync(join(dir, entry), { force: true });
      removed += 1;
    } catch {
      // A locked file must not break the article delete.
    }
  }
  return removed;
}

/** The next free index for an article inside the covers directory. */
function nextCoverIndex(dir, articleId) {
  let entries = [];
  try {
    entries = readdirSync(dir);
  } catch {
    entries = [];
  }
  let max = 0;
  for (const entry of entries) {
    if (!isCoverFilenameOfArticle(entry, articleId)) continue;
    const match = COVER_FILENAME_PATTERN.exec(entry);
    const index = match ? Number(match[1]) : 0;
    if (Number.isFinite(index) && index > max) max = index;
  }
  return max + 1;
}
